import { createMemoryAdapter, createRouter } from "@canonical/router-core";
import { RouterProvider } from "@canonical/router-react";
import { render, screen } from "@testing-library/react";
import type { ReactElement } from "react";
import { describe, expect, it } from "vitest";
import { LENS_ROUTES } from "../../../../testing/fixtures.js";
import FilterBar from "./FilterBar.js";

/** Render `ui` under the fixtures' router at `href`. */
const renderAt = (href: string, ui: ReactElement) =>
  render(
    <RouterProvider
      router={createRouter(LENS_ROUTES, { adapter: createMemoryAdapter(href) })}
    >
      {ui}
    </RouterProvider>,
  );

describe("FilterBar", () => {
  it("is a named group holding the facets, the chips, then More filters", () => {
    renderAt(
      "/catalog",
      <FilterBar
        chips={<span>zone 1</span>}
        facets={<button type="button">Zone</button>}
      />,
    );
    const bar = screen.getByRole("group", { name: "Facets" });
    expect(bar.tagName).toBe("FIELDSET");
    expect(bar.closest<HTMLElement>("[data-region]")?.dataset.region).toBe(
      "filter-bar",
    );
    const slots = [...bar.querySelectorAll("[data-slot]")].map(
      (slot) => (slot as HTMLElement).dataset.slot,
    );
    expect(slots).toEqual(["facets", "chips", "more"]);
  });

  it("renders the chips only when given", () => {
    renderAt("/catalog", <FilterBar facets="Zone" />);
    expect(
      screen.getByRole("group").querySelector('[data-slot="chips"]'),
    ).toBeNull();
  });

  it("links More filters to the current address with the sheet open", () => {
    renderAt("/catalog?q=cen", <FilterBar facets="Zone" />);
    expect(screen.getByRole("link", { name: "More filters" })).toHaveAttribute(
      "href",
      "/catalog?q=cen&sheet=filter",
    );
  });

  it("marks More filters needed only when the bar is folded", () => {
    renderAt("/catalog", <FilterBar facets="Zone" />);
    expect(screen.getByRole("link")).not.toHaveClass("is-needed");
  });

  it("marks More filters needed when the lens has facets the bar does not hold", () => {
    renderAt("/catalog", <FilterBar facets="Zone" folded />);
    expect(screen.getByRole("link")).toHaveClass("more", "is-needed");
  });

  it("applies custom className and passes native props through", () => {
    renderAt(
      "/catalog",
      <FilterBar className="custom-class" data-testid="bar" facets="Zone" />,
    );
    const bar = screen.getByTestId("bar");
    expect(bar.className).toContain("ds filter-bar");
    expect(bar.className).toContain("custom-class");
  });
});
